\begin{align}
h_{[1^k]}(q) &= (h_{[1]}(q))^k,\\
h_{[k]}(q) &= h_{[1]}(q^k),\\
h_{[2,1]}(q) &= h_{[1]}(q^2) h_{[1]}(q).
\end{align}

The first integral also simplifies and becomes

\begin{equation}
h_{[1]}(q) = \oint_{\mathcal{C}_{\infty}} \frac{dz}{z} :e^{\phi(z)}
\frac{q^{N + z \partial_z} - 1}{q - 1} e^{-\phi(z)}:\,
\end{equation}

where $\phi(z) = \phi_{-}(z) - \phi_{+}(z)$ and the normal ordering acts on $p_n$ and $\frac{\partial}{\partial p_n}$\footnote{One can fermionize the bosonic operators so that $:e^{\phi(z)}: \sim
  \bar{\psi}(z)$, $:e^{-\phi(z)}: \sim \psi(z)$. This leads to the fermionic construction of $GL(\infty)$ Casimirs.}. Notice also that $h_{[1]}(q)$ with different values of $q$ commute:

\begin{equation}
[h_{[1]}(q) , h_{[1]}(q')] =0\,.
\end{equation}

The values of $h_{[1]}(q)$ are expressed through the Casimir operators for the group $GL(\infty)$:

\begin{equation}
h_{[1]}(q) \chi_R = \left( q^{N-\frac{1}{2}} C_R(q) + \frac{q^N - 1}{q - 1}\right) \chi_R\,,
\end{equation}

where $C_R(e^{\hbar}) = \sum_{i \geq 1} \left( e^{\hbar \left(R_i - i
      + \frac{1}{2}\right)} - e^{\hbar \left( - i +
      \frac{1}{2}\right)} \right) = \sum_{n \geq 0} \frac{\hbar^n}{n!}
C_R(n)$ is the generating function of the Casimirs $C_R(n) = \sum_{i
  \geq 1} \left[ \left( R_i - i + \frac{1}{2} \right)^n - (-i +
  \frac{1}{2})^n \right]$.
